const raw =
  $json.candidates?.[0]?.content?.parts?.[0]?.text ??
  $json.body?.candidates?.[0]?.content?.parts?.[0]?.text ??
  '';

let profile = {};
try {
  let s = String(raw).trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '');
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) s = s.slice(a, b + 1);
  profile = JSON.parse(s);
} catch (e) {
  throw new Error('Could not parse Gemini profile JSON: ' + e.message + '\nRaw: ' + raw);
}

const arr = (v) => Array.isArray(v)
  ? v.filter(x => x !== null && x !== undefined && String(x).trim() !== '').map(String)
  : [];
const text = (v) => v === null || v === undefined ? '' : String(v);

profile.name = text(profile.name);
profile.email = text(profile.email);
profile.phone = text(profile.phone);
profile.education = text(profile.education);
profile.experience = text(profile.experience);
profile.skills = arr(profile.skills);
profile.projects = arr(profile.projects);
profile.preferred_roles = arr(profile.preferred_roles);
profile.preferred_locations = arr(profile.preferred_locations);
profile.work_mode = text(profile.work_mode);
profile.years_experience = text(profile.years_experience);

return [{
  json: {
    profile,
    resume_text: String($('Extract Resume Text').first().json.text || '')
  }
}];

const p = $json.profile || $json;

const clean = (a) => {
  if (!Array.isArray(a)) return [];

  return [...new Set(
    a
      .map(x => {
        if (typeof x === 'string') return x.trim();
        if (x && typeof x === 'object') {
          return String(x.name || x.title || x.role || '').trim();
        }
        return '';
      })
      .filter(Boolean)
  )];
};

const roles = clean(
  p.preferred_roles ||
  p.target_roles ||
  p.job_roles ||
  p.desired_roles
);

const skills = clean(p.skills);

const locations = clean(
  p.preferred_locations ||
  p.locations
);

const projects = clean(p.projects);

const workMode = String(p.work_mode || '').trim();

const experience = String(p.years_experience || '').trim();

const education = String(p.education || '').trim();

return [{
  json: {
    profile: p,
    resume_text: $json.resume_text || '',

    searchRoles: roles.slice(0, 6),

    searchLocations: locations.length
      ? locations.slice(0, 6)
      : ['India', 'Remote', 'Worldwide'],

    skillText: skills.slice(0, 15).join(', '),

    roleText: roles.join(', '),

    experience,

    education,

    projectText: projects.slice(0, 8).join(', '),

    workMode,

    minMatch: 70,

    maxJobsToMatch: 120
  }
}];

const roles = Array.isArray($json.searchRoles)
  ? $json.searchRoles
  : [];

const locations = Array.isArray($json.searchLocations)
  ? $json.searchLocations
  : ['India', 'Remote', 'Worldwide'];

const profile = $json.profile || {};

const queries = [];

for (const role of roles) {
  for (const location of locations) {
    queries.push({
      json: {
        query: `site:cutshort.io/job/ ${role} ${location}`,
        role: role,
        location: location,
        candidate_profile: profile
      }
    });
  }
}

return queries;

