const responses = $input.all();
const queries = $('Create Search Queries').all();

// Get the original resume text once.
// .first() avoids the paired-item problem.
const resumeText = $('Extract Resume Text').first().json.text || '';

const output = [];

for (let i = 0; i < responses.length; i++) {

  const response = responses[i]?.json || {};
  const q = queries[i]?.json || {};

  const results = Array.isArray(response.results)
    ? response.results
    : [];

  for (const r of results) {

    if (!r?.url) continue;

    output.push({
      json: {
        url: String(r.url).split('#')[0],
        title: r.title || '',
        snippet: r.content || '',
        rawContent: r.raw_content || '',

        searchRole: q.role || '',
        searchLocation: q.location || '',

        profile: q.profile || {},

        // ⭐ Add the full resume to every job
        candidate_resume: resumeText
      }
    });

  }
}

return output;

// ============================================================
// PARSE MATCH - ROBUST FINAL VERSION
// ============================================================

const items = $input.all();

// ============================================================
// URL CLEANER
// ============================================================

function cleanUrl(value) {
  if (!value) return "";

  let url = String(value).trim();

  // Remove Markdown URL format:
  // [https://example.com](https://example.com)
  const markdownMatch = url.match(/\]\((https?:\/\/[^)\s]+)\)/);

  if (markdownMatch) {
    return markdownMatch[1].trim();
  }

  // Extract normal URL if extra text exists
  const plainUrl = url.match(/https?:\/\/[^\s)\]"']+/);

  if (plainUrl) {
    return plainUrl[0].trim();
  }

  return url;
}

// ============================================================
// GEMINI JSON PARSER
// ============================================================

function parseGeminiText(value) {
  if (!value) return null;

  // Already an object
  if (typeof value === "object") {
    return value;
  }

  let text = String(value).trim();

  // Remove Markdown code fences
  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // Find JSON object if Gemini added extra text
  const firstBrace = text.indexOf("{");
  const lastBrace = text.lastIndexOf("}");

  if (firstBrace !== -1 && lastBrace !== -1) {
    text = text.substring(firstBrace, lastBrace + 1);
  }

  try {
    return JSON.parse(text);
  } catch (error) {
    return null;
  }
}

// ============================================================
// PROCESS ITEMS
// ============================================================

const output = [];

for (const item of items) {

  const input = item.json;

  // ==========================================================
  // FIND GEMINI RESPONSE
  // ==========================================================

  let parsed = null;

  // Gemini response normally comes in "text"
  if (input.text) {
    parsed = parseGeminiText(input.text);
  }

  // Alternative output field
  if (!parsed && input.output) {
    parsed = parseGeminiText(input.output);
  }

  // Alternative response field
  if (!parsed && input.response) {
    parsed = parseGeminiText(input.response);
  }

  // If item already contains parsed fields
  if (!parsed && input.job_title) {
    parsed = input;
  }

  // ==========================================================
  // IF GEMINI RESPONSE CANNOT BE PARSED
  // SKIP THE BAD ITEM
  // ==========================================================

  if (!parsed) {
    continue;
  }

  // ==========================================================
  // JOB URL
  // ==========================================================

  const jobUrl = cleanUrl(
    parsed.job_url ||
    input.individual_job_url ||
    input.original_job_url ||
    input.url ||
    ""
  );

  // ==========================================================
  // FINAL CLEAN OUTPUT
  // ==========================================================

  output.push({
    json: {

      job_title: parsed.job_title || "",

      company: parsed.company || "",

      job_url: jobUrl,

      location: parsed.location || "",

      work_mode: parsed.work_mode || "",

      experience_required:
        parsed.experience_required || "",

      // ========================================================
      // MATCH SCORE
      // ========================================================

      match_score: Number(parsed.match_score) || 0,

      eligible: Boolean(parsed.eligible),

      is_individual_job:
        Boolean(parsed.is_individual_job),

      // ========================================================
      // INDIVIDUAL SCORES
      // ========================================================

      role_match:
        Number(parsed.role_match) || 0,

      skill_match:
        Number(parsed.skill_match) || 0,

      experience_match:
        Number(parsed.experience_match) || 0,

      project_match:
        Number(parsed.project_match) || 0,

      education_match:
        Number(parsed.education_match) || 0,

      location_workmode_match:
        Number(parsed.location_workmode_match) || 0,

      // ========================================================
      // SKILLS
      // Convert arrays to readable text for Google Sheets
      // ========================================================

      matched_skills:
        Array.isArray(parsed.matched_skills)
          ? parsed.matched_skills.join(", ")
          : String(parsed.matched_skills || ""),

      missing_skills:
        Array.isArray(parsed.missing_skills)
          ? parsed.missing_skills.join(", ")
          : String(parsed.missing_skills || ""),

      required_skills_missing:
        Array.isArray(parsed.required_skills_missing)
          ? parsed.required_skills_missing.join(", ")
          : String(parsed.required_skills_missing || ""),

      preferred_skills_missing:
        Array.isArray(parsed.preferred_skills_missing)
          ? parsed.preferred_skills_missing.join(", ")
          : String(parsed.preferred_skills_missing || ""),

      // ========================================================
      // REASON
      // ========================================================

      reason: parsed.reason || ""
    }
  });
}

// ============================================================
// RETURN FINAL ITEMS
// ============================================================

return output;

