  const data = item.json;

  const raw =
    data.candidates?.[0]?.content?.parts?.[0]?.text ??
    data.body?.candidates?.[0]?.content?.parts?.[0]?.text ??
    data.response?.candidates?.[0]?.content?.parts?.[0]?.text ??
