const items = $input.all();

return items
  .filter(item => {
    const url = item.json.url || item.json.link || '';

    return url.includes('cutshort.io/job/');
  })
  .map(item => {
    const url = item.json.url || item.json.link;

    return {
      json: {
        ...item.json,
        individual_job_url: url
      }
    };
  });

const candidate =
  $('Automatic Search Settings').first().json.profile || {};

return $input.all().map(item => {
  const job = item.json;

  return {
    json: {
      ...job,

      original_job_url:
        job.individual_job_url ||
        job.url ||
        job.job_url ||
        "",

      candidate_profile: candidate
    }
  };
});
